$.Yh=A.agW('// Skinning vert-shader //////////\n/*\n If the current vertex is affected by bones then the vertex position and\n normal will be transformed by the bone matrices. Each vertex wil have up \n to 4 bone indices (inBoneIndex) and bone weights (inBoneWeights).\n \n The indices are used to index into the array of bone matrices \n (BoneMatrixArray) to get the required bone matrix for transformation. The \n amount of influence a particular bone has on a vertex is determined by the\n weights which should always total 1. So if a vertex is affected by 2 bones \n the vertex position in world space is given by the following equation:\n \n position = (BoneMatrixArray[Index0] * inVertex) * Weight0 + \n (BoneMatrixArray[Index1] * inVertex) * Weight1\n \n The same proceedure is applied to the normals but the translation part of \n the transformation is ignored.\n \n After this the position is multiplied by the view and projection matrices \n only as the bone matrices already contain the model transform for this \n particular mesh. The two-step transformation is required because lighting \n will not work properly in clip space.\n */\n#define ENABLE_SKINNING\nattribute highp vec3 inVertex;\t\t// vertex-data\n\nattribute mediump vec4 inBoneIndex;\nattribute mediump vec4 inBoneWeight;\n\t\t  \n// skinning mesh part: bone\nuniform mediump int BoneCount;\nuniform highp   mat4 BoneMatrixArray[32];\n//uniform highp   mat3 BoneMatrixArrayIT[8];\n/*\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n{\n\thighp vec4 srcVert = vec4(inVertex, 1.0);\n\t// On PowerVR SGX it is possible to index the components of a vector\n\t// with the [] operator. However this can cause trouble with PC\n\t// emulation on some hardware so we "rotate" the vectors instead.\n\tmediump ivec4 boneIndex = ivec4(inBoneIndex);\n\tmediump vec4 boneWeight = inBoneWeight;\n\thighp mat4 boneMatrix = BoneMatrixArray[boneIndex.x];\n\thighp mat3 normalMatrix = mat3(boneMatrix);//BoneMatrixArrayIT[boneIndex.x];\n\n\tobjVert = boneMatrix * srcVert * boneWeight.x;\n\tobjNormal = normalMatrix * inNormal * boneWeight.x;\n\t\n\t// PowerVR SGX supports uniforms in the for loop and nested conditionals.\n\t// For performance reasons, the code below should be like this:\n\t//\tfor (lowp int i = 1; i < BoneCount; ++i)\n\t//\t{\n\t//\t\tboneIndex = boneIndex.yzwx;\n\t//\t\tboneWeight = boneWeight.yzwx;\n\t//\t\n\t//\t\tboneMatrix = BoneMatrixArray[boneIndex.x];\n\t//\t\tnormalMatrix = BoneMatrixArrayIT[boneIndex.x];\n\t//\t\n\t//\t\tif (boneWeight.x > 0.0)\n\t//\t\t{\n\t//\t\t\tobjVert += boneMatrix * vec4(inVertex, 1.0) * boneWeight.x;\n\t//\t\t\tobjNormal += normalMatrix * inNormal * boneWeight.x;\n\t//\t\t}\n\t//\t}\n\t// However this code causes a severe crash on PCEmulation\n\t// in some ATI hardware due to a very limited loop support.\n\t// If you are targeting SGX, please, modify the code below.\n\tfor (lowp int i = 1; i < BoneCount; ++i)\n\t{\n\t\t// "rotate" the vector components\n\t\tboneIndex = boneIndex.yzwx;\n\t\tboneWeight = boneWeight.yzwx;\n\t\t\n\t\tboneMatrix = BoneMatrixArray[boneIndex.x];\n\t\tnormalMatrix = mat3(boneMatrix);//BoneMatrixArrayIT[boneIndex.x];\n\t\t\n\t\tobjVert += boneMatrix * srcVert * boneWeight.x;\n\t\tobjNormal += normalMatrix * inNormal * boneWeight.x;\n\t}\n\tobjNormal = normalize(objNormal);\n}\n*/\n\n// skinning vertex: discard for-loop, so extend to whole code\n// (ps: iPad2 has some problem when using for-loop (4 times) in shader)\n#ifdef ENABLE_NORMAL\nattribute mediump vec3 inNormal;\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n#else\nvoid ComputeSkinningVertex(out highp vec4 objVert)\n#endif // ENABLE_NORMAL\n{\n\thighp vec4 srcVert = vec4(inVertex, 1.0);\n\t// On PowerVR SGX it is possible to index the components of a vector\n\t// with the [] operator. However this can cause trouble with PC\n\t// emulation on some hardware so we "rotate" the vectors instead.\n\tmediump ivec4 boneIndex = ivec4(inBoneIndex + 0.5);\n\n\tobjVert = BoneMatrixArray[boneIndex.x] * srcVert * inBoneWeight.x;\n#ifdef ENABLE_NORMAL\n\tobjNormal = mat3(BoneMatrixArray[boneIndex.x]) * inNormal * inBoneWeight.x;\n#endif // ENABLE_NORMAL\n\tif (BoneCount > 1)\n\t{\n\t\tobjVert += BoneMatrixArray[boneIndex.y] * srcVert * inBoneWeight.y;\n#ifdef ENABLE_NORMAL\n\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.y]) * inNormal * inBoneWeight.y;\n#endif // ENABLE_NORMAL\n\t\tif (BoneCount > 2)\n\t\t{\n\t\t\tobjVert += BoneMatrixArray[boneIndex.z] * srcVert * inBoneWeight.z;\n#ifdef ENABLE_NORMAL\n\t\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.z]) * inNormal * inBoneWeight.z;\n#endif // ENABLE_NORMAL\n\t\t\tif (BoneCount > 3)\n\t\t\t{\n\t\t\t\tobjVert += BoneMatrixArray[boneIndex.w] * srcVert * inBoneWeight.w;\n#ifdef ENABLE_NORMAL\n\t\t\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.w]) * inNormal * inBoneWeight.w;\n#endif // ENABLE_NORMAL\n\t\t\t}\n\t\t}\n\t}\n#ifdef ENABLE_NORMAL\n\tobjNormal = normalize(objNormal);\n#endif // ENABLE_NORMAL\n}\n\n// Simple vert-shader //////////\n// NOTICE: "Skinning.es2.vert" must be added before this file\n#ifndef ENABLE_SKINNING\nattribute highp vec3 inVertex;\t\t// vertex-data\n#endif // ENABLE_SKINNING\n\n// attribute mediump vec4 inColor;\t\t// as diffuse-ambient material\n\nuniform lowp vec4 uColor;\nvarying lowp vec4 DestinationColor;\n// eye-space for camera-viewer\n//uniform mat4 Projection;\nuniform highp mat4 ModelviewProjection;\n\t\t  \nvoid main(void)\n{\n\thighp vec4 objVert = vec4(inVertex, 1.0);\n\n#ifdef ENABLE_SKINNING\n\tif (BoneCount > 0)\n\t{\n\t\tComputeSkinningVertex(objVert);\n\t}\n#endif // ENABLE_SKINNING\n\n\t//DestinationColor = vec4(1,1,1, 1); // use white color\n    DestinationColor = uColor; // use uniform color\n    gl_Position = ModelviewProjection * objVert;\t// pre-compute Projection * Modelview\n}\n\n',u.q)
$.alw=A.agW("// Skybox vert-shader: via cubemap //////////\nattribute highp vec3 inVertex;\t\t// vertex-data\n\nuniform lowp vec4 uColor;\nvarying lowp vec4 DestinationColor;\nvarying mediump vec3 TexCoordDirOut;\n// eye-space for camera-viewer\nuniform highp mat4 ModelviewProjection;\n\nvoid main(void)\n{\n\thighp vec4 objVert = vec4(inVertex, 1.0);\n\n\tTexCoordDirOut = objVert.xyz;\n\tDestinationColor = uColor;\n\tgl_Position = ModelviewProjection * objVert;\t// pre-compute Projection * Modelview\n}\n\n",u.s)
$.j9=A.agW("// Rect vert-shader //////////\nattribute highp vec3 inVertex;\t\t// vertex-data\n//attribute mediump vec4 inColor;\t\t// as diffuse-ambient material\nattribute mediump vec2 inTexCoord;\n\nuniform lowp vec4 uColor;\n\n// eye-space for camera-viewer\nuniform highp mat4 Projection;\t\t// ortho-matrix\nuniform highp mat4 Model;\t\t\t// model-matrix (by screen-object)\n\nuniform highp mat3 uTexMatrix;\t\t// texture-matrix (uv mapping)\nvarying mediump vec2 TextureCoordOut;\nvarying lowp vec4 DestinationColor;\n\nvoid main(void)\n{\n\tDestinationColor = uColor;\n\tTextureCoordOut = (uTexMatrix * vec3(inTexCoord, 1.0)).xy;\n\t// TextureCoordOut = inTexCoord;\n    gl_Position = Projection * Model * vec4(inVertex, 1.0);\n}\n\n","// Rect frag-shader //////////\nvarying mediump vec2 TextureCoordOut;\nvarying lowp vec4 DestinationColor;\n\nuniform sampler2D SamplerDiffuse;\t// GL_TEXTURE0\n\nvoid main(void)\n{\n    gl_FragColor = texture2D(SamplerDiffuse, TextureCoordOut) * DestinationColor;\n//    gl_FragColor = vec4(1,1,1,1);\n}\n\n")
$.alx=A.avF('#define ENABLE_NORMAL \n// Skinning vert-shader //////////\n/*\n If the current vertex is affected by bones then the vertex position and\n normal will be transformed by the bone matrices. Each vertex wil have up \n to 4 bone indices (inBoneIndex) and bone weights (inBoneWeights).\n \n The indices are used to index into the array of bone matrices \n (BoneMatrixArray) to get the required bone matrix for transformation. The \n amount of influence a particular bone has on a vertex is determined by the\n weights which should always total 1. So if a vertex is affected by 2 bones \n the vertex position in world space is given by the following equation:\n \n position = (BoneMatrixArray[Index0] * inVertex) * Weight0 + \n (BoneMatrixArray[Index1] * inVertex) * Weight1\n \n The same proceedure is applied to the normals but the translation part of \n the transformation is ignored.\n \n After this the position is multiplied by the view and projection matrices \n only as the bone matrices already contain the model transform for this \n particular mesh. The two-step transformation is required because lighting \n will not work properly in clip space.\n */\n#define ENABLE_SKINNING\nattribute highp vec3 inVertex;\t\t// vertex-data\n\nattribute mediump vec4 inBoneIndex;\nattribute mediump vec4 inBoneWeight;\n\t\t  \n// skinning mesh part: bone\nuniform mediump int BoneCount;\nuniform highp   mat4 BoneMatrixArray[32];\n//uniform highp   mat3 BoneMatrixArrayIT[8];\n/*\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n{\n\thighp vec4 srcVert = vec4(inVertex, 1.0);\n\t// On PowerVR SGX it is possible to index the components of a vector\n\t// with the [] operator. However this can cause trouble with PC\n\t// emulation on some hardware so we "rotate" the vectors instead.\n\tmediump ivec4 boneIndex = ivec4(inBoneIndex);\n\tmediump vec4 boneWeight = inBoneWeight;\n\thighp mat4 boneMatrix = BoneMatrixArray[boneIndex.x];\n\thighp mat3 normalMatrix = mat3(boneMatrix);//BoneMatrixArrayIT[boneIndex.x];\n\n\tobjVert = boneMatrix * srcVert * boneWeight.x;\n\tobjNormal = normalMatrix * inNormal * boneWeight.x;\n\t\n\t// PowerVR SGX supports uniforms in the for loop and nested conditionals.\n\t// For performance reasons, the code below should be like this:\n\t//\tfor (lowp int i = 1; i < BoneCount; ++i)\n\t//\t{\n\t//\t\tboneIndex = boneIndex.yzwx;\n\t//\t\tboneWeight = boneWeight.yzwx;\n\t//\t\n\t//\t\tboneMatrix = BoneMatrixArray[boneIndex.x];\n\t//\t\tnormalMatrix = BoneMatrixArrayIT[boneIndex.x];\n\t//\t\n\t//\t\tif (boneWeight.x > 0.0)\n\t//\t\t{\n\t//\t\t\tobjVert += boneMatrix * vec4(inVertex, 1.0) * boneWeight.x;\n\t//\t\t\tobjNormal += normalMatrix * inNormal * boneWeight.x;\n\t//\t\t}\n\t//\t}\n\t// However this code causes a severe crash on PCEmulation\n\t// in some ATI hardware due to a very limited loop support.\n\t// If you are targeting SGX, please, modify the code below.\n\tfor (lowp int i = 1; i < BoneCount; ++i)\n\t{\n\t\t// "rotate" the vector components\n\t\tboneIndex = boneIndex.yzwx;\n\t\tboneWeight = boneWeight.yzwx;\n\t\t\n\t\tboneMatrix = BoneMatrixArray[boneIndex.x];\n\t\tnormalMatrix = mat3(boneMatrix);//BoneMatrixArrayIT[boneIndex.x];\n\t\t\n\t\tobjVert += boneMatrix * srcVert * boneWeight.x;\n\t\tobjNormal += normalMatrix * inNormal * boneWeight.x;\n\t}\n\tobjNormal = normalize(objNormal);\n}\n*/\n\n// skinning vertex: discard for-loop, so extend to whole code\n// (ps: iPad2 has some problem when using for-loop (4 times) in shader)\n#ifdef ENABLE_NORMAL\nattribute mediump vec3 inNormal;\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n#else\nvoid ComputeSkinningVertex(out highp vec4 objVert)\n#endif // ENABLE_NORMAL\n{\n\thighp vec4 srcVert = vec4(inVertex, 1.0);\n\t// On PowerVR SGX it is possible to index the components of a vector\n\t// with the [] operator. However this can cause trouble with PC\n\t// emulation on some hardware so we "rotate" the vectors instead.\n\tmediump ivec4 boneIndex = ivec4(inBoneIndex + 0.5);\n\n\tobjVert = BoneMatrixArray[boneIndex.x] * srcVert * inBoneWeight.x;\n#ifdef ENABLE_NORMAL\n\tobjNormal = mat3(BoneMatrixArray[boneIndex.x]) * inNormal * inBoneWeight.x;\n#endif // ENABLE_NORMAL\n\tif (BoneCount > 1)\n\t{\n\t\tobjVert += BoneMatrixArray[boneIndex.y] * srcVert * inBoneWeight.y;\n#ifdef ENABLE_NORMAL\n\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.y]) * inNormal * inBoneWeight.y;\n#endif // ENABLE_NORMAL\n\t\tif (BoneCount > 2)\n\t\t{\n\t\t\tobjVert += BoneMatrixArray[boneIndex.z] * srcVert * inBoneWeight.z;\n#ifdef ENABLE_NORMAL\n\t\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.z]) * inNormal * inBoneWeight.z;\n#endif // ENABLE_NORMAL\n\t\t\tif (BoneCount > 3)\n\t\t\t{\n\t\t\t\tobjVert += BoneMatrixArray[boneIndex.w] * srcVert * inBoneWeight.w;\n#ifdef ENABLE_NORMAL\n\t\t\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.w]) * inNormal * inBoneWeight.w;\n#endif // ENABLE_NORMAL\n\t\t\t}\n\t\t}\n\t}\n#ifdef ENABLE_NORMAL\n\tobjNormal = normalize(objNormal);\n#endif // ENABLE_NORMAL\n}\n\n// Skybox Reflect vert-shader: via cubemap //////////\n// NOTICE 1: ENABLE_NORMAL must be defined first\n// NOTICE 2: "Skinning.es2.vert" must be added for skinning\n#ifndef ENABLE_SKINNING\nattribute highp vec3 inVertex;\t\t// vertex-data\nattribute mediump vec3 inNormal;\n#endif // ENABLE_SKINNING\n\n// object space\nuniform mediump vec3 EyePosition;\t\t\t// eye as camera origin\nuniform lowp vec4 uColor;\n\nvarying lowp vec4 DestinationColor;\nvarying mediump vec3 TexCoordDirOut;\n\n// space transformation\nuniform highp mat4 Model;\nuniform highp mat4 ModelviewProjection;\n\nvoid main(void)\n{\n\thighp vec4 objVert = vec4(inVertex, 1.0);\n\tmediump vec3 objNormal = inNormal;\n\n#ifdef ENABLE_SKINNING\n\tif (BoneCount > 0)\n\t{\n\t\tComputeSkinningVertex(objVert, objNormal);\n\t}\n#endif // ENABLE_SKINNING\n\n\tmediump vec3 eyeDir = normalize(objVert.xyz - EyePosition);\t// by object-space\n\tmediump vec3 reflectDir = reflect(eyeDir, objNormal);\t\t// by object-space\n\treflectDir = mat3(Model) * reflectDir;\t\t\t\t\t\t// by world-space\n\n\t// Swizzle to match skybox-cubemap orientation (rotXNeg90)\n\tTexCoordDirOut.x = -reflectDir.x;\n\tTexCoordDirOut.y = reflectDir.z;\n\tTexCoordDirOut.z = -reflectDir.y;\n\n\tDestinationColor = uColor;\n\n    gl_Position = ModelviewProjection * objVert;\t// pre-compute Projection * Modelview\n}\n\n',u.s)
A.als('#define ENABLE_NORMAL \n// Skinning vert-shader //////////\n/*\n If the current vertex is affected by bones then the vertex position and\n normal will be transformed by the bone matrices. Each vertex wil have up \n to 4 bone indices (inBoneIndex) and bone weights (inBoneWeights).\n \n The indices are used to index into the array of bone matrices \n (BoneMatrixArray) to get the required bone matrix for transformation. The \n amount of influence a particular bone has on a vertex is determined by the\n weights which should always total 1. So if a vertex is affected by 2 bones \n the vertex position in world space is given by the following equation:\n \n position = (BoneMatrixArray[Index0] * inVertex) * Weight0 + \n (BoneMatrixArray[Index1] * inVertex) * Weight1\n \n The same proceedure is applied to the normals but the translation part of \n the transformation is ignored.\n \n After this the position is multiplied by the view and projection matrices \n only as the bone matrices already contain the model transform for this \n particular mesh. The two-step transformation is required because lighting \n will not work properly in clip space.\n */\n#define ENABLE_SKINNING\nattribute highp vec3 inVertex;\t\t// vertex-data\n\nattribute mediump vec4 inBoneIndex;\nattribute mediump vec4 inBoneWeight;\n\t\t  \n// skinning mesh part: bone\nuniform mediump int BoneCount;\nuniform highp   mat4 BoneMatrixArray[32];\n//uniform highp   mat3 BoneMatrixArrayIT[8];\n/*\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n{\n\thighp vec4 srcVert = vec4(inVertex, 1.0);\n\t// On PowerVR SGX it is possible to index the components of a vector\n\t// with the [] operator. However this can cause trouble with PC\n\t// emulation on some hardware so we "rotate" the vectors instead.\n\tmediump ivec4 boneIndex = ivec4(inBoneIndex);\n\tmediump vec4 boneWeight = inBoneWeight;\n\thighp mat4 boneMatrix = BoneMatrixArray[boneIndex.x];\n\thighp mat3 normalMatrix = mat3(boneMatrix);//BoneMatrixArrayIT[boneIndex.x];\n\n\tobjVert = boneMatrix * srcVert * boneWeight.x;\n\tobjNormal = normalMatrix * inNormal * boneWeight.x;\n\t\n\t// PowerVR SGX supports uniforms in the for loop and nested conditionals.\n\t// For performance reasons, the code below should be like this:\n\t//\tfor (lowp int i = 1; i < BoneCount; ++i)\n\t//\t{\n\t//\t\tboneIndex = boneIndex.yzwx;\n\t//\t\tboneWeight = boneWeight.yzwx;\n\t//\t\n\t//\t\tboneMatrix = BoneMatrixArray[boneIndex.x];\n\t//\t\tnormalMatrix = BoneMatrixArrayIT[boneIndex.x];\n\t//\t\n\t//\t\tif (boneWeight.x > 0.0)\n\t//\t\t{\n\t//\t\t\tobjVert += boneMatrix * vec4(inVertex, 1.0) * boneWeight.x;\n\t//\t\t\tobjNormal += normalMatrix * inNormal * boneWeight.x;\n\t//\t\t}\n\t//\t}\n\t// However this code causes a severe crash on PCEmulation\n\t// in some ATI hardware due to a very limited loop support.\n\t// If you are targeting SGX, please, modify the code below.\n\tfor (lowp int i = 1; i < BoneCount; ++i)\n\t{\n\t\t// "rotate" the vector components\n\t\tboneIndex = boneIndex.yzwx;\n\t\tboneWeight = boneWeight.yzwx;\n\t\t\n\t\tboneMatrix = BoneMatrixArray[boneIndex.x];\n\t\tnormalMatrix = mat3(boneMatrix);//BoneMatrixArrayIT[boneIndex.x];\n\t\t\n\t\tobjVert += boneMatrix * srcVert * boneWeight.x;\n\t\tobjNormal += normalMatrix * inNormal * boneWeight.x;\n\t}\n\tobjNormal = normalize(objNormal);\n}\n*/\n\n// skinning vertex: discard for-loop, so extend to whole code\n// (ps: iPad2 has some problem when using for-loop (4 times) in shader)\n#ifdef ENABLE_NORMAL\nattribute mediump vec3 inNormal;\nvoid ComputeSkinningVertex(out highp vec4 objVert, out mediump vec3 objNormal)\n#else\nvoid ComputeSkinningVertex(out highp vec4 objVert)\n#endif // ENABLE_NORMAL\n{\n\thighp vec4 srcVert = vec4(inVertex, 1.0);\n\t// On PowerVR SGX it is possible to index the components of a vector\n\t// with the [] operator. However this can cause trouble with PC\n\t// emulation on some hardware so we "rotate" the vectors instead.\n\tmediump ivec4 boneIndex = ivec4(inBoneIndex + 0.5);\n\n\tobjVert = BoneMatrixArray[boneIndex.x] * srcVert * inBoneWeight.x;\n#ifdef ENABLE_NORMAL\n\tobjNormal = mat3(BoneMatrixArray[boneIndex.x]) * inNormal * inBoneWeight.x;\n#endif // ENABLE_NORMAL\n\tif (BoneCount > 1)\n\t{\n\t\tobjVert += BoneMatrixArray[boneIndex.y] * srcVert * inBoneWeight.y;\n#ifdef ENABLE_NORMAL\n\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.y]) * inNormal * inBoneWeight.y;\n#endif // ENABLE_NORMAL\n\t\tif (BoneCount > 2)\n\t\t{\n\t\t\tobjVert += BoneMatrixArray[boneIndex.z] * srcVert * inBoneWeight.z;\n#ifdef ENABLE_NORMAL\n\t\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.z]) * inNormal * inBoneWeight.z;\n#endif // ENABLE_NORMAL\n\t\t\tif (BoneCount > 3)\n\t\t\t{\n\t\t\t\tobjVert += BoneMatrixArray[boneIndex.w] * srcVert * inBoneWeight.w;\n#ifdef ENABLE_NORMAL\n\t\t\t\tobjNormal += mat3(BoneMatrixArray[boneIndex.w]) * inNormal * inBoneWeight.w;\n#endif // ENABLE_NORMAL\n\t\t\t}\n\t\t}\n\t}\n#ifdef ENABLE_NORMAL\n\tobjNormal = normalize(objNormal);\n#endif // ENABLE_NORMAL\n}\n\n// Simple-lighting vert-shader //////////\n// NOTICE: "Skinning.es2.vert" must be added before this file\n#ifndef ENABLE_SKINNING\nattribute highp vec3 inVertex;\t\t// vertex-data\nattribute mediump vec3 inNormal;\n#endif // ENABLE_SKINNING\n\nuniform lowp vec4 uColor;\n\n// eye-space for camera-viewer\n//uniform mat4 Projection;\nuniform mat4 ModelviewProjection;\n\n// color combined by light and material\nuniform lowp vec3 ColorAmbient;\t\t// ambient RGB \nuniform lowp vec4 ColorDiffuse;\t\t// diffuse RGBA\nuniform mediump vec4 ColorSpecular;\t// specular RGB, w: shininess\n\n// object-space\nuniform vec3 EyePosition;\t\t// eye as camera origin\nuniform vec3 LightPosition;\t\t// parallel light\n\n// shader variable: from vert to frag\nvarying lowp vec4 DestinationColor;\n\nvoid main(void) {\n\thighp vec4 objVert = vec4(inVertex, 1.0);\n\tmediump vec3 objNormal = inNormal;\n\n#ifdef ENABLE_SKINNING\n\tif (BoneCount > 0)\n\t{\n\t\tComputeSkinningVertex(objVert, objNormal);\n\t}\n#endif // ENABLE_SKINNING\n\n\t// object-space: normal, light-position, eye-position\n\tvec3 N = objNormal;\n\tvec3 L = LightPosition;\t\t\t\t\t\t\t// parallel light source\n\tvec3 E = normalize(EyePosition - objVert.xyz);\t// vertex to eye\n\tvec3 H = normalize(L + E);\n\n\tfloat df = max(0.0, dot(N, L));\n\tfloat sf = max(0.0, dot(N, H));\n\tsf = pow(sf, ColorSpecular.w);\n\n\tlowp vec3 AmbientDiffuseSpecular = (ColorAmbient + ColorDiffuse.rgb * df) + ColorSpecular.rgb * sf;\n\n\tDestinationColor = vec4(AmbientDiffuseSpecular, uColor.a);\n\t// DestinationColor = vec4((N + vec3(1.0) / 2.0), uColor.a);\t\t// normal\n\t// DestinationColor = uColor;\n\n//\tgl_Position = Projection * Modelview * objVert;\t// pre-compute Projection * Modelview\n\tgl_Position = ModelviewProjection * objVert;\t// pre-compute Projection * Modelview\n}\n\n',u.q)
